window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4b472bc531a99543"]={"versions": [{"id": "FIG-4b472bc531a99543", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Konstanten im Rahmen der Interaktion zwischen AUTOSAR und Behavior Modeling Tools (BMT). Das Diagramm stellt das Metamodell-Mapping zwischen AUTOSAR-Konstanten-Definitionen (Paket <code>Constants</code>) und Verhaltensmodell-Komponenten (<code>BM Software-Component</code> aus dem Namensraum <code>Behavior Modeling</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Klassenhierarchie und Schnittstellen umfassen folgende Elemente:</p>\n<ul class=\"fig-list\"><li><code>ARElement</code>: Basisklasse des AUTOSAR-Metamodells.\n</li><li><code>Constants::Constant</code>: Spezialisierung von <code>ARElement</code>, dient als abstrakte oder allgemeine Basis für Konstanten.\n</li><li><code>Constants::ConstantPrimitive</code>: Spezialisierung von <code>Constant</code> zur Repräsentation primitiver Konstantenwerte.\n</li><li>Konkrete Spezialisierungen von <code>ConstantPrimitive</code>:\n<ul class=\"fig-list\"><li><code>Constants::StringConstant</code> mit Attribut <code>+ value: String</code>\n</li><li><code>Constants::OpaqueConstant</code> mit Attribut <code>+ value: String</code>\n</li><li><code>Constants::NumericConstant</code> mit Attribut <code>+ value: Float</code>\n</li><li><code>Constants::CharConstant</code> mit Attribut <code>+ value: String</code>\n</li><li><code>Constants::BooleanConstant</code> mit Attribut <code>+ value: Boolean</code>\n</li></ul>\n</li><li><code>BM Software-Component</code> (mit Stereotyp/Herkunft <code>(from Behavior Modeling)</code>): Externe Entität der Verhaltensmodellierung, die Abhängigkeiten (<code>&lt;&lt;import&gt;&gt;</code> bzw. gerichtete Abhängigkeitspfeile) zu <code>Constant</code>, <code>ConstantPrimitive</code>, <code>NumericConstant</code> und <code>BooleanConstant</code> aufweist.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Ablauf- oder Zustandslogik. Die gestrichelten Abhängigkeitspfeile kennzeichnen die Import- bzw. Verwendungsbeziehungen einer Verhaltensmodellkomponente (<code>BM Software-Component</code>) bezüglich der definierten Konstantenklassen, insbesondere den gezielten Import von <code>NumericConstant</code> und <code>BooleanConstant</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Leitfaden für BMT-Adapter und Modelltransformatoren. Numerische Konstanten werden über <code>NumericConstant</code> mit dem generischen Typ <code>Float</code> abgebildet, welcher implizit ganzzahlige Werte mit abdeckt. Die Abhängigkeiten verdeutlichen, welche Konstantenprimitive direkt von der Modellierungsumgebung importiert und unterstützt werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-04fe9ee08ef19dde", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Konstanten im Rahmen der Interaktion zwischen AUTOSAR und Behavior Modeling Tools (BMT). Das Diagramm stellt das Metamodell-Mapping zwischen AUTOSAR-Konstanten-Definitionen (Paket <code>Constants</code>) und Verhaltensmodell-Komponenten (<code>BM Software-Component</code> aus dem Namensraum <code>Behavior Modeling</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Klassenhierarchie und Schnittstellen umfassen folgende Elemente:</p>\n<ul class=\"fig-list\"><li><code>ARElement</code>: Basisklasse des AUTOSAR-Metamodells.\n</li><li><code>Constants::Constant</code>: Spezialisierung von <code>ARElement</code>, dient als abstrakte oder allgemeine Basis für Konstanten.\n</li><li><code>Constants::ConstantPrimitive</code>: Spezialisierung von <code>Constant</code> zur Repräsentation primitiver Konstantenwerte.\n</li><li>Konkrete Spezialisierungen von <code>ConstantPrimitive</code>:\n<ul class=\"fig-list\"><li><code>Constants::StringConstant</code> mit Attribut <code>+ value: String</code>\n</li><li><code>Constants::OpaqueConstant</code> mit Attribut <code>+ value: String</code>\n</li><li><code>Constants::NumericConstant</code> mit Attribut <code>+ value: Float</code>\n</li><li><code>Constants::CharConstant</code> mit Attribut <code>+ value: String</code>\n</li><li><code>Constants::BooleanConstant</code> mit Attribut <code>+ value: Boolean</code>\n</li></ul>\n</li><li><code>BM Software-Component</code> (mit Stereotyp/Herkunft <code>(from Behavior Modeling)</code>): Externe Entität der Verhaltensmodellierung, die Abhängigkeiten (<code>&lt;&lt;import&gt;&gt;</code> bzw. gerichtete Abhängigkeitspfeile) zu <code>Constant</code>, <code>ConstantPrimitive</code>, <code>NumericConstant</code> und <code>BooleanConstant</code> aufweist.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Ablauf- oder Zustandslogik. Die gestrichelten Abhängigkeitspfeile kennzeichnen die Import- bzw. Verwendungsbeziehungen einer Verhaltensmodellkomponente (<code>BM Software-Component</code>) bezüglich der definierten Konstantenklassen, insbesondere den gezielten Import von <code>NumericConstant</code> und <code>BooleanConstant</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Leitfaden für BMT-Adapter und Modelltransformatoren. Numerische Konstanten werden über <code>NumericConstant</code> mit dem generischen Typ <code>Float</code> abgebildet, welcher implizit ganzzahlige Werte mit abdeckt. Die Abhängigkeiten verdeutlichen, welche Konstantenprimitive direkt von der Modellierungsumgebung importiert und unterstützt werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-4b472bc531a99543", "to": "FIG-04fe9ee08ef19dde", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
